package dev.cazajefes;
import java.util.*;
import org.bukkit.*;
import org.bukkit.attribute.Attribute;
import org.bukkit.entity.*;
import org.bukkit.event.*;
import org.bukkit.event.entity.*;
import org.bukkit.persistence.PersistentDataType;
import org.bukkit.scheduler.BukkitTask;
import org.bukkit.util.Vector;
/** Shared controller for all encounter minions; native ranged attacks retain their own cooldowns. */
final class AnimalMinions implements Listener {
 private static final class Unit{final LivingEntity entity,parent;final int tier;long path,hit,shot;Unit(LivingEntity e,LivingEntity p,int t){entity=e;parent=p;tier=t;}}
 private final Map<UUID,Unit> units=new HashMap<>();private final Map<UUID,Projectile> projectiles=new HashMap<>();private final BukkitTask task;private final CazaJefesPlugin plugin;
 private static final NamespacedKey MARK=new NamespacedKey("cazajefes","aggressive_animal"),SHOT=new NamespacedKey("cazajefes","minion_shot_damage");
 AnimalMinions(CazaJefesPlugin plugin){this.plugin=plugin;task=plugin.getServer().getScheduler().runTaskTimer(plugin,this::tick,5,5);}
 static boolean animal(EntityType type){return switch(type){case BEE,FOX,HOGLIN,SNIFFER,POLAR_BEAR,WOLF,GOAT,TURTLE,LLAMA,TRADER_LLAMA,COW,MOOSHROOM,PIG,SHEEP,CHICKEN,RABBIT,HORSE,DONKEY,MULE,CAMEL,PANDA,AXOLOTL,OCELOT,CAT,PARROT,ARMADILLO,DOLPHIN,SQUID,GLOW_SQUID->true;default->false;};}
 void track(LivingEntity entity,LivingEntity parent,int tier){if(animal(entity.getType())){var health=entity.getAttribute(Attribute.MAX_HEALTH);if(health!=null){health.setBaseValue(CombatPower.minionHealth(tier));entity.setHealth(health.getValue());}var armor=entity.getAttribute(Attribute.ARMOR);if(armor!=null)armor.setBaseValue(8+tier*2);entity.getPersistentDataContainer().set(MARK,PersistentDataType.BYTE,(byte)1);if(entity instanceof Mob mob)PassiveHostility.prepare(mob);}entity.setCanPickupItems(false);units.put(entity.getUniqueId(),new Unit(entity,parent,tier));}
 private void tick(){long now=System.currentTimeMillis();projectiles.values().removeIf(p->{if(!p.isValid()||p.getShooter() instanceof LivingEntity owner&&(!owner.isValid()||owner.isDead())){p.remove();return true;}return false;});for(var iterator=units.entrySet().iterator();iterator.hasNext();){Unit unit=iterator.next().getValue();LivingEntity entity=unit.entity;if(!entity.isValid()||entity.isDead()||!unit.parent.isValid()||unit.parent.isDead()||!entity.getWorld().equals(unit.parent.getWorld())){if(entity.isValid())entity.remove();iterator.remove();continue;}
  Player target=entity.getWorld().getPlayers().stream().filter(p->CombatGuard.eligible(p)&&CombatHitbox.distanceSquared(p.getEyeLocation(),entity)<=576).min(java.util.Comparator.comparingDouble(p->p.getLocation().distanceSquared(entity.getLocation()))).orElse(null);if(target==null)continue;
  if(entity instanceof Armadillo a&&!ArmadilloMotion.open(a))continue;if(entity instanceof Bee bee){bee.setAnger(24000);bee.setHasStung(false);}if(entity instanceof Mob mob)mob.setTarget(target);
  boolean ranged=MinionTactics.ranged(entity.getType())||entity.getType()==EntityType.DROWNED&&entity.getEquipment()!=null&&entity.getEquipment().getItemInMainHand().getType()==Material.TRIDENT;
  double distance=Math.sqrt(CombatHitbox.distanceSquared(target.getEyeLocation(),entity));boolean visible=ranged?entity.hasLineOfSight(target):CombatHitbox.visible(target,entity);var move=MinionTactics.move(ranged,visible,distance);
  if(!(entity instanceof Shulker)){Vector delta=target.getLocation().toVector().subtract(entity.getLocation().toVector()),flat=delta.clone().setY(0);if(flat.lengthSquared()>.01){flat.normalize();Vector direction=move==MinionTactics.Move.RETREAT?flat.clone().multiply(-1):move==MinionTactics.Move.STRAFE?new Vector(-flat.getZ(),0,flat.getX()).multiply((entity.getEntityId()%2==0?1:-1)):flat;
   Location waypoint=move==MinionTactics.Move.APPROACH?target.getLocation():entity.getLocation().add(direction.clone().multiply(3));if(entity instanceof Mob mob&&now>=unit.path){mob.getPathfinder().moveTo(waypoint,ranged?1.1:1.4);unit.path=now+750;}
   if(visible){boolean flight=entity instanceof Flying||entity.getType()==EntityType.BEE||entity.getType()==EntityType.PARROT,water=entity.getLocation().getBlock().isLiquid();double speed=move==MinionTactics.Move.STRAFE?.14:ranged?.26:.34;Vector motion=direction.multiply(speed);motion.setY(entity.getVelocity().getY());if(flight||water)motion.setY(Math.max(-.3,Math.min(.3,delta.getY()*.1)));else{var ahead=entity.getLocation().add(motion.clone().setY(0).normalize().multiply(.8)).getBlock();if(!ahead.isPassable()&&ahead.getRelative(0,1,0).isPassable()&&entity.isOnGround())motion.setY(.4);if(ahead.getRelative(0,-1,0).isPassable()&&entity.isOnGround())continue;}if(EncounterSafety.clear(entity,entity.getLocation().add(motion.getX(),Math.max(0,motion.getY()),motion.getZ())))entity.setVelocity(motion);else if(entity.isOnGround()&&motion.getY()>0)entity.setVelocity(new Vector(0,.42,0));}
  }}
  if(ranged){if(visible&&distance<=16&&now>=unit.shot&&(entity.getType()==EntityType.LLAMA||entity.getType()==EntityType.TRADER_LLAMA||entity.getType()==EntityType.SNOW_GOLEM)&&projectiles.size()<64){unit.shot=now+2500;Vector aim=target.getEyeLocation().toVector().subtract(entity.getEyeLocation().toVector()).normalize().multiply(1.6);Projectile shot=entity.getType()==EntityType.SNOW_GOLEM?entity.launchProjectile(Snowball.class,aim):entity.launchProjectile(LlamaSpit.class,aim);shot.getPersistentDataContainer().set(SHOT,PersistentDataType.DOUBLE,8.0+unit.tier*2);projectiles.put(shot.getUniqueId(),shot);plugin.getServer().getScheduler().runTaskLater(plugin,()->{projectiles.remove(shot.getUniqueId());shot.remove();},60);}continue;}
  if(animal(entity.getType())&&visible&&distance<=2.8&&now>=unit.hit){target.damage(8+unit.tier*2,entity);unit.hit=now+1000;CosmeticFX.emit(Particle.CRIT,entity.getLocation().add(0,.6,0),5,.2,.3,.2,.03);}
 }}
 @EventHandler(priority=EventPriority.HIGH,ignoreCancelled=true)public void projectile(EntityDamageByEntityEvent event){Double damage=event.getDamager().getPersistentDataContainer().get(SHOT,PersistentDataType.DOUBLE);if(damage==null)return;if(!(event.getEntity() instanceof Player player)||!CombatGuard.eligible(player)){event.setCancelled(true);return;}SafeDamage.setBase(event,damage);}
 static void capHit(EntityDamageEvent event,double maximum){if(event.isCancelled())return;double finalDamage=event.getFinalDamage(),limit=CombatPower.minionHitLimit(maximum);if(Double.isFinite(finalDamage)&&finalDamage>limit)SafeDamage.scale(event,limit/finalDamage);}
 @EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=true)public void defend(EntityDamageByEntityEvent event){if(event.getEntity() instanceof LivingEntity animal&&animal.getPersistentDataContainer().has(MARK,PersistentDataType.BYTE))capHit(event,animal.getMaxHealth());}
 void stop(){task.cancel();for(var unit:units.values())if(unit.entity.isValid())unit.entity.remove();units.clear();for(var shot:projectiles.values())shot.remove();projectiles.clear();}
}
